#include <iostream>
using namespace std;

class Hinh {
public:
    virtual double dienTich() { return 0; }
};

class Vuong : public Hinh {
    double canh;
public:
    Vuong(double c) : canh(c) {}
    double dienTich() override { return canh * canh; }
};

int main() {
    Hinh* h = new Vuong(4);
    cout << h->dienTich() << endl;
    delete h;
    return 0;
}
